def linspace(
    start, stop, num=50, endpoint=True, retstep=False, dtype=None, axis=0
):
    if dtype is None:
        dtypes_to_resolve = [
            getattr(start, "dtype", type(start)),
            getattr(stop, "dtype", type(stop)),
            float,
        ]
        dtype = dtypes.result_type(*dtypes_to_resolve)
    else:
        dtype = standardize_dtype(dtype)
    start = convert_to_tensor(start, dtype=dtype)
    stop = convert_to_tensor(stop, dtype=dtype)

    # Handle negative num
    if tf.is_tensor(num):
        num_value = tf.get_static_value(num)
        if num_value is not None and int(num_value) < 0:
            raise ValueError(
                f"`num` must be a non-negative integer. Received: num={num_value}"
            )
    else:
        if num < 0:
            raise ValueError(
                f"`num` must be a non-negative integer. Received: num={num}"
            )

    step = tf.convert_to_tensor(np.nan, dtype=start.dtype)

    if tf.is_tensor(num):
        if endpoint:
            result = tf.linspace(start, stop, num, axis=axis)
            step = tf.where(
                num > 1,
                (stop - start) / tf.cast(num - 1, start.dtype),
                step,
            )
        else:
            # tf.linspace doesn't support endpoint=False, so we manually handle it
            step = tf.where(
                num > 0,
                (stop - start) / tf.cast(num, start.dtype),
                step,
            )
            new_stop = tf.cast(stop, step.dtype) - step
            # Use `stop` when num <= 1
            new_stop = tf.where(num > 1, new_stop, tf.cast(stop, step.dtype))
            start_cast = tf.cast(start, new_stop.dtype)
            result = tf.linspace(start_cast, new_stop, num, axis=axis)
    else:
        if endpoint:
            result = tf.linspace(start, stop, num, axis=axis)
            if num > 1:
                step = (stop - start) / tf.cast(num - 1, start.dtype)
        else:
            # tf.linspace doesn't support endpoint=False, so we manually handle it
            if num > 0:
                step = (stop - start) / tf.cast(num, start.dtype)
            if num > 1:
                new_stop = tf.cast(stop, step.dtype) - step
                start = tf.cast(start, new_stop.dtype)
                result = tf.linspace(start, new_stop, num, axis=axis)
            else:
                result = tf.linspace(start, stop, num, axis=axis)

    if dtype is not None:
        if "int" in dtype:
            result = tf.floor(result)
        result = tf.cast(result, dtype)
    if retstep:
        return (result, step)
    else:
        return result

